+
+// reportedEvent is the action and interface name of an emitted event.
+type reportedEvent struct {
+	action string
+	ifname string
+}
+
+// drainEvents closes events and returns what was emitted, in order.
+func drainEvents(events chan aggregatedEvent) []reportedEvent {
+	close(events)
+
+	var got []reportedEvent
+	for ev := range events {
+		got = append(got, reportedEvent{action: ev.Action, ifname: ev.Attributes["ifname"]})
+	}
+
+	return got
+}
+
+// stitchedWatcher returns a watcher that reported the link with index 7 as
+// the host-side stitch interface of its veth-stitch link.
+func stitchedWatcher() *netlinkWatcher {
+	return &netlinkWatcher{
+		container: &clabruntime.GenericContainer{Names: []string{"n1"}},
+		reported: map[int]reportedInterface{
+			7: {
+				attributes: map[string]string{"ifname": "clab-s-0011aabb", "alias": "e1-1"},
+				since:      time.Now(),
+			},
+		},
+	}
+}
+
+// TestEmitReportsRenamedLinkDeleted checks that a link reported under another
+// name than before is first reported deleted under the old name, so clients
+// do not keep both, and is then new to them.
+func TestEmitReportsRenamedLinkDeleted(t *testing.T) {
+	events := make(chan aggregatedEvent, 8)
+	registry := newNetlinkRegistry(t.Context(), events, false, false, 0)
+	watcher := stitchedWatcher()
+
+	link := &netlink.Veth{LinkAttrs: netlink.LinkAttrs{Index: 7, Name: "e1-1", MTU: 1500}}
+	watcher.emit(registry, "update", snapshotFromLink(link))
+	watcher.emit(registry, "update", snapshotFromLink(link))
+
+	want := []reportedEvent{
+		{action: "delete", ifname: "clab-s-0011aabb"},
+		{action: "create", ifname: "e1-1"},
+		{action: "update", ifname: "e1-1"},
+	}
+	if got := drainEvents(events); !slices.Equal(got, want) {
+		t.Fatalf("events = %v, want %v", got, want)
+	}
+}
+
+// TestEmitDeletesLinkAsLastReported checks that a deletion names the link as
+// clients know it, also when its stitch interface is already gone.
+func TestEmitDeletesLinkAsLastReported(t *testing.T) {
+	events := make(chan aggregatedEvent, 8)
+	registry := newNetlinkRegistry(t.Context(), events, false, false, 0)
+	watcher := stitchedWatcher()
+
+	link := &netlink.Veth{LinkAttrs: netlink.LinkAttrs{Index: 7, Name: "e1-1", MTU: 1500}}
+	watcher.emit(registry, "delete", snapshotFromLink(link))
+
+	want := []reportedEvent{{action: "delete", ifname: "clab-s-0011aabb"}}
+	if got := drainEvents(events); !slices.Equal(got, want) {
+		t.Fatalf("events = %v, want %v", got, want)
+	}
+
+	if _, ok := watcher.reported[7]; ok {
+		t.Fatal("deleted link is still tracked as reported")
+	}
+}
+
+// TestEmitStatsReportsRenamedLinkFirst checks that counters of a link reported
+// under another name before follow its deletion under that name and its
+// creation without counters.
+func TestEmitStatsReportsRenamedLinkFirst(t *testing.T) {
+	events := make(chan aggregatedEvent, 8)
+	registry := newNetlinkRegistry(t.Context(), events, false, true, time.Second)
+	watcher := stitchedWatcher()
+
+	link := &netlink.Veth{LinkAttrs: netlink.LinkAttrs{
+		Index:      7,
+		Name:       "e1-1",
+		MTU:        1500,
+		Statistics: &netlink.LinkStatistics{RxBytes: 10},
+	}}
+	watcher.emitStats(registry, snapshotFromLink(link), ifaceStatsMetrics{
+		Timestamp: time.Now(),
+	})
+	close(events)
+
+	var got []reportedEvent
+	for ev := range events {
+		got = append(got, reportedEvent{action: ev.Action, ifname: ev.Attributes["ifname"]})
+
+		_, hasCounters := ev.Attributes["rx_bytes"]
+		if hasCounters != (ev.Action == "stats") {
+			t.Fatalf("%s event has counters: %v", ev.Action, hasCounters)
+		}
+	}
+
+	want := []reportedEvent{
+		{action: "delete", ifname: "clab-s-0011aabb"},
+		{action: "create", ifname: "e1-1"},
+		{action: "stats", ifname: "e1-1"},
+	}
+	if !slices.Equal(got, want) {
+		t.Fatalf("events = %v, want %v", got, want)
+	}
+
+	if _, ok := watcher.reported[7].attributes["rx_bytes"]; ok {
+		t.Fatal("counters are kept as what the link was reported as")
+	}
+}
+
+// TestReportStitchMarksLeavesUnmarkedLinks checks that links without a marked
+// stitch interface, or reported too long ago, are not reported again.
+func TestReportStitchMarksLeavesUnmarkedLinks(t *testing.T) {
+	events := make(chan aggregatedEvent, 8)
+	registry := newNetlinkRegistry(t.Context(), events, false, false, 0)
+	watcher := &netlinkWatcher{
+		container: &clabruntime.GenericContainer{Names: []string{"n1"}},
+	}
+
+	recent := &netlink.Veth{LinkAttrs: netlink.LinkAttrs{Index: 7, Name: "e1-1", MTU: 1500}}
+	old := &netlink.Veth{LinkAttrs: netlink.LinkAttrs{Index: 8, Name: "e1-2", MTU: 1500}}
+	states := map[int]ifaceSnapshot{7: snapshotFromLink(recent), 8: snapshotFromLink(old)}
+	watcher.emit(registry, "create", states[7])
+	watcher.emit(registry, "create", states[8])
+	watcher.reported[8] = reportedInterface{
+		attributes: watcher.reported[8].attributes,
+		since:      time.Now().Add(-2 * stitchMarkWindow),
+	}
+
+	watcher.reportStitchMarks(states, registry)
+
+	want := []reportedEvent{{action: "create", ifname: "e1-1"}, {action: "create", ifname: "e1-2"}}
+	if got := drainEvents(events); !slices.Equal(got, want) {
+		t.Fatalf("events = %v, want %v", got, want)
+	}
+}

package events

import (
	"context"
	"errors"
	"fmt"
	"maps"
	"math"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/charmbracelet/log"
	gotc "github.com/florianl/go-tc"
	clabconstants "github.com/srl-labs/containerlab/constants"
	clabcore "github.com/srl-labs/containerlab/core"
	clablabruntime "github.com/srl-labs/containerlab/labruntime"
	clablinks "github.com/srl-labs/containerlab/links"
	clabnetem "github.com/srl-labs/containerlab/netem"
	clabruntime "github.com/srl-labs/containerlab/runtime"
	clabutils "github.com/srl-labs/containerlab/utils"
	"github.com/vishvananda/netlink"
	"github.com/vishvananda/netns"
	"golang.org/x/sys/unix"
)

type netlinkRegistry struct {
	ctx                    context.Context
	mu                     sync.Mutex
	watchers               map[string]*netlinkWatcher
	events                 chan<- aggregatedEvent
	includeInitialSnapshot bool
	includeStats           bool
	statsInterval          time.Duration
}

func newNetlinkRegistry(
	ctx context.Context,
	events chan<- aggregatedEvent,
	includeInitialSnapshot bool,
	includeStats bool,
	statsInterval time.Duration,
) *netlinkRegistry {
	return &netlinkRegistry{
		ctx:                    ctx,
		watchers:               make(map[string]*netlinkWatcher),
		events:                 events,
		includeInitialSnapshot: includeInitialSnapshot,
		includeStats:           includeStats,
		statsInterval:          statsInterval,
	}
}

func (r *netlinkRegistry) Start(container *clabruntime.GenericContainer) {
	clone := cloneContainer(container)
	if clone == nil {
		return
	}

	id := clone.ID
	if id == "" {
		id = clone.ShortID
	}

	if id == "" {
		return
	}

	r.mu.Lock()
	if _, exists := r.watchers[id]; exists {
		r.mu.Unlock()

		return
	}

	watcherCtx, cancel := context.WithCancel(r.ctx)
	watcher := &netlinkWatcher{
		container:       clone,
		cancel:          cancel,
		done:            make(chan struct{}),
		includeSnapshot: r.includeInitialSnapshot,
		includeStats:    r.includeStats,
		statsInterval:   r.statsInterval,
	}

	r.watchers[id] = watcher
	r.mu.Unlock()

	go watcher.run(watcherCtx, r)
}

func (r *netlinkRegistry) Stop(id string) {
	if id == "" {
		return
	}

	r.mu.Lock()
	watcher, ok := r.watchers[id]
	if ok {
		delete(r.watchers, id)
	}
	r.mu.Unlock()

	if !ok {
		return
	}

	watcher.cancel()
	<-watcher.done
}

func (r *netlinkRegistry) remove(id string, watcher *netlinkWatcher) {
	if id == "" {
		return
	}

	r.mu.Lock()
	defer r.mu.Unlock()

	if current, ok := r.watchers[id]; ok && current == watcher {
		delete(r.watchers, id)
	}
}

func (r *netlinkRegistry) HandleContainerEvent(
	runtime clabruntime.ContainerRuntime,
	ev clabruntime.ContainerEvent,
) {
	if !strings.EqualFold(ev.Type, clabruntime.EventTypeContainer) {
		return
	}

	action := strings.ToLower(ev.Action)

	switch action {
	case clabruntime.EventActionStart,
		clabruntime.EventActionUnpause,
		clabruntime.EventActionRestart:
		container := containerFromEvent(runtime, ev)
		if container != nil {
			r.Start(container)
		}
	case clabruntime.EventActionDie,
		clabruntime.EventActionStop,
		clabruntime.EventActionDestroy,
		clabruntime.EventActionKill:
		id := ev.ActorFullID
		if id == "" {
			id = ev.ActorID
		}

		r.Stop(id)
	}
}

func cloneContainer(container *clabruntime.GenericContainer) *clabruntime.GenericContainer {
	if container == nil {
		return nil
	}

	clone := &clabruntime.GenericContainer{
		Names:   append([]string{}, container.Names...),
		ID:      container.ID,
		ShortID: container.ShortID,
		Labels:  cloneStringMap(container.Labels),
	}

	if clone.ShortID == "" {
		clone.ShortID = clabutils.ShortID(clone.ID)
	}

	if container.Runtime == nil {
		return nil
	}

	clone.SetRuntime(container.Runtime)

	return clone
}

func containerFromEvent(
	runtime clabruntime.ContainerRuntime,
	ev clabruntime.ContainerEvent,
) *clabruntime.GenericContainer {
	attributes := ev.Attributes

	name := ev.ActorName
	if name == "" && attributes != nil {
		name = attributes["name"]
	}

	id := ev.ActorFullID
	if id == "" {
		id = ev.ActorID
	}

	if id == "" && name == "" {
		return nil
	}

	short := ev.ActorID
	if short == "" {
		short = id
	}

	container := &clabruntime.GenericContainer{
		ID:      id,
		ShortID: clabutils.ShortID(short),
	}

	if name != "" {
		container.Names = []string{name}
	}

	if attributes != nil {
		for _, key := range []string{
			clabconstants.Containerlab,
			clabconstants.NodeName,
			clabconstants.RootNodeName,
		} {
			if v := attributes[key]; v != "" {
				if container.Labels == nil {
					container.Labels = map[string]string{}
				}

				container.Labels[key] = v
			}
		}
	}

	if container.ShortID == "" {
		container.ShortID = clabutils.ShortID(container.ID)
	}

	if runtime != nil {
		container.SetRuntime(runtime)
	}

	return container
}

type netlinkWatcher struct {
	container       *clabruntime.GenericContainer
	cancel          context.CancelFunc
	done            chan struct{}
	includeSnapshot bool
	includeStats    bool
	statsInterval   time.Duration
	nsHandle        netns.NsHandle
	// reported holds what each link was last reported as, by its index in the
	// container's namespace.
	reported map[int]reportedInterface
}

// reportedInterface is what a link was last reported as.
type reportedInterface struct {
	attributes map[string]string
	// since is when the link was first reported.
	since time.Time
}

// stitchMarkWindow is how long after a link is first reported its host-side
// stitch interface is looked for while the link itself does not change.
// Deploying a veth-stitch link marks that interface right after it creates the
// link, without a change in the node's namespace.
var stitchMarkWindow = time.Minute

// Retry settings for a watcher that could not subscribe to link updates.
var (
	watchMaxAttempts   = 5
	watchRetryDelay    = time.Second
	watchMaxRetryDelay = 10 * time.Second
)

func (w *netlinkWatcher) run(ctx context.Context, registry *netlinkRegistry) {
	defer close(w.done)
	if w.container == nil {
		return
	}

	defer registry.remove(w.container.ID, w)

	containerName := firstContainerName(w.container)
	if w.container.Runtime == nil {
		log.Debugf("container %s has no runtime, skipping netlink watcher", containerName)

		return
	}

	// The states outlive a subscription, so a resubscribe only reports what
	// changed while no subscription was active.
	states := make(map[int]ifaceSnapshot)

	var statsSamples map[int]ifaceStatsSample
	if w.includeStats {
		statsSamples = make(map[int]ifaceStatsSample)
	}

	initial := true
	failures := 0
	delay := watchRetryDelay

	for {
		subscribed, err := w.watch(ctx, registry, states, statsSamples, initial)
		if ctx.Err() != nil {
			return
		}

		if subscribed {
			initial = false
			failures = 0
			delay = watchRetryDelay

			log.Warnf(
				"netlink subscription for container %s ended, resubscribing: %v",
				containerName,
				err,
			)
		} else {
			failures++
			if failures >= watchMaxAttempts {
				log.Warnf("stopped watching interfaces of container %s: %v", containerName, err)

				return
			}

			log.Debugf(
				"failed to watch interfaces of container %s, retrying in %s: %v",
				containerName,
				delay,
				err,
			)
		}

		select {
		case <-time.After(delay):
		case <-ctx.Done():
			return
		}

		delay = min(delay*2, watchMaxRetryDelay)
	}
}

// watch subscribes to link updates in the container's namespace and handles
// them until ctx ends or the subscription fails. It reports whether it
// subscribed. The subscription lists the existing links itself, so no change
// between listing and subscribing is lost.
func (w *netlinkWatcher) watch(
	ctx context.Context,
	registry *netlinkRegistry,
	states map[int]ifaceSnapshot,
	statsSamples map[int]ifaceStatsSample,
	initial bool,
) (bool, error) {
	nsPath, err := waitForNamespacePath(ctx, w.container.Runtime, w.container.ID)
	if err != nil {
		return false, fmt.Errorf("failed to resolve netns: %w", err)
	}

	nsHandle, err := netns.GetFromPath(nsPath)
	if err != nil {
		return false, fmt.Errorf("failed to open netns: %w", err)
	}
	defer nsHandle.Close()

	w.nsHandle = nsHandle

	netHandle, err := netlink.NewHandleAt(nsHandle)
	if err != nil {
		return false, fmt.Errorf("failed to create netlink handle: %w", err)
	}
	defer netHandle.Close()

	netemQuery := newNetemQuerier(nsHandle)
	defer netemQuery.Close()

	netemInfos := netemQuery.Query()

	updates := make(chan netlink.LinkUpdate, 32)
	done := make(chan struct{})
	defer close(done)

	var (
		errMu     sync.Mutex
		lastError error
	)

	opts := netlink.LinkSubscribeOptions{
		Namespace:    &nsHandle,
		ListExisting: true,
		// An interrupted listing is reported here too. It needs no action:
		// links that changed during the listing also arrive as updates.
		ErrorCallback: func(err error) {
			log.Debugf(
				"netlink subscription for container %s: %v",
				firstContainerName(w.container),
				err,
			)

			errMu.Lock()
			lastError = err
			errMu.Unlock()
		},
	}

	if err := netlink.LinkSubscribeWithOptions(updates, done, opts); err != nil {
		return false, fmt.Errorf("failed to subscribe to netlink updates: %w", err)
	}

	var vanished map[int]struct{}
	if len(states) > 0 {
		vanished = w.removeVanishedLinks(netHandle, states, statsSamples, registry)
	}

	// Set up netem polling interval (reuse stats interval or default to 1s).
	netemPollInterval := w.statsInterval
	if netemPollInterval == 0 {
		netemPollInterval = time.Second
	}
	netemTicker := time.NewTicker(netemPollInterval)
	defer netemTicker.Stop()

	var (
		ticker  *time.Ticker
		tickerC <-chan time.Time
	)
	if w.includeStats && w.statsInterval > 0 {
		ticker = time.NewTicker(w.statsInterval)
		tickerC = ticker.C
		defer ticker.Stop()
	}

	for {
		select {
		case <-tickerC:
			w.collectAndEmitStats(netHandle, states, statsSamples, registry)
		case <-netemTicker.C:
			w.pollNetemChanges(states, registry, netemQuery)
			w.reportStitchMarks(states, registry)
		case <-ctx.Done():
			return true, nil
		case update, ok := <-updates:
			if !ok {
				errMu.Lock()
				err := lastError
				errMu.Unlock()

				if err == nil {
					err = errors.New("update channel closed")
				}

				return true, err
			}

			// Replies to the listing carry NLM_F_MULTI, notifications do not.
			if update.Header.Flags&unix.NLM_F_MULTI != 0 {
				w.processExisting(
					states,
					statsSamples,
					update.Link,
					netemInfos,
					vanished,
					registry,
					initial,
				)

				continue
			}

			w.processUpdate(states, statsSamples, update, registry, netemQuery)
		}
	}
}

// processExisting records a link listed when the subscription started. On the
// first subscription a new link is reported as a snapshot when requested; after
// a resubscribe it is reported as created.
//
// The listing can be older than the check in removeVanishedLinks, so it can
// still hold a link that check reported as deleted. Such a link is skipped; its
// deletion notification follows and is ignored, as the link is not tracked.
func (w *netlinkWatcher) processExisting(
	states map[int]ifaceSnapshot,
	statsSamples map[int]ifaceStatsSample,
	link netlink.Link,
	netemInfos map[int]netemInfo,
	vanished map[int]struct{},
	registry *netlinkRegistry,
	initial bool,
) {
	if link == nil || link.Attrs() == nil {
		return
	}

	if _, ok := vanished[link.Attrs().Index]; ok {
		return
	}

	snapshot := withNetem(snapshotFromLink(link), netemInfos)
	previous, exists := states[snapshot.Index]

	if exists && snapshot.equal(previous) {
		return
	}

	states[snapshot.Index] = snapshot
	if statsSamples != nil {
		if sample, ok := newStatsSample(snapshot, time.Now()); ok {
			statsSamples[snapshot.Index] = sample
		}
	}

	switch {
	case exists:
		w.emit(registry, "update", snapshot)
	case !initial:
		w.emit(registry, "create", snapshot)
	case w.includeSnapshot:
		w.emit(registry, "snapshot", snapshot)
	}
}

// removeVanishedLinks reports the links that were deleted while no
// subscription was active and returns their indexes.
func (w *netlinkWatcher) removeVanishedLinks(
	netHandle *netlink.Handle,
	states map[int]ifaceSnapshot,
	statsSamples map[int]ifaceStatsSample,
	registry *netlinkRegistry,
) map[int]struct{} {
	current, err := snapshotInterfaces(netHandle)
	if err != nil {
		log.Debugf(
			"failed to list interfaces of container %s: %v",
			firstContainerName(w.container),
			err,
		)

		return nil
	}

	vanished := map[int]struct{}{}

	for idx, snapshot := range states {
		if _, ok := current[idx]; ok {
			continue
		}

		vanished[idx] = struct{}{}

		delete(states, idx)
		delete(statsSamples, idx)
		w.emit(registry, "delete", snapshot)
	}

	return vanished
}

func (w *netlinkWatcher) processUpdate(
	states map[int]ifaceSnapshot,
	statsSamples map[int]ifaceStatsSample,
	update netlink.LinkUpdate,
	registry *netlinkRegistry,
	netemQuery *netemQuerier,
) {
	if update.Link == nil {
		return
	}

	attrs := update.Link.Attrs()
	if attrs == nil {
		return
	}

	snapshot := snapshotFromLink(update.Link)
	previous, exists := states[snapshot.Index]

	switch update.Header.Type {
	case unix.RTM_DELLINK:
		// A link that is not tracked was never reported, or its deletion was
		// already reported when the links were listed again after a resubscribe.
		if !exists {
			return
		}

		delete(states, snapshot.Index)
		delete(statsSamples, snapshot.Index)
		w.emit(registry, "delete", previous)
	case unix.RTM_NEWLINK:
		// Query netem info for this interface
		snapshot = withNetem(snapshot, netemQuery.Query())

		if exists && snapshot.equal(previous) {
			return
		}

		action := "create"
		if exists {
			action = "update"
		}

		states[snapshot.Index] = snapshot
		if w.includeStats && statsSamples != nil {
			if sample, ok := newStatsSample(snapshot, time.Now()); ok {
				statsSamples[snapshot.Index] = sample
			}
		}
		w.emit(registry, action, snapshot)
	}
}

// pollNetemChanges checks for netem changes and emits update events.
func (w *netlinkWatcher) pollNetemChanges(
	states map[int]ifaceSnapshot,
	registry *netlinkRegistry,
	netemQuery *netemQuerier,
) {
	netemInfos := netemQuery.Query()

	for idx, snapshot := range states {
		previous := snapshot
		info, hasNetem := netemInfos[idx]

		if hasNetem {
			snapshot.HasNetem = true
			snapshot.Delay = info.Delay
			snapshot.Jitter = info.Jitter
			snapshot.PacketLoss = info.PacketLoss
			snapshot.Rate = info.Rate
			snapshot.Corruption = info.Corruption
		} else if snapshot.HasNetem {
			// Netem was removed
			snapshot.HasNetem = false
			snapshot.Delay = ""
			snapshot.Jitter = ""
			snapshot.PacketLoss = 0
			snapshot.Rate = 0
			snapshot.Corruption = 0
		}

		if !snapshot.equal(previous) {
			states[idx] = snapshot
			w.emit(registry, "update", snapshot)
		}
	}
}

// reportStitchMarks reports the links whose host-side stitch interface got
// marked after their last event. Only veths reported under their own name
// shortly before are looked at: the node's end of a veth-stitch link is a veth
// and is marked while its lab deploys.
func (w *netlinkWatcher) reportStitchMarks(
	states map[int]ifaceSnapshot,
	registry *netlinkRegistry,
) {
	for idx, snapshot := range states {
		reported, ok := w.reported[idx]
		if !ok || snapshot.Type != "veth" ||
			reported.attributes["ifname"] != snapshot.Name ||
			time.Since(reported.since) > stitchMarkWindow {
			continue
		}

		if interfaceAttributes(w.container, snapshot)["ifname"] != snapshot.Name {
			w.emit(registry, "update", snapshot)
		}
	}
}

// emit reports an event of a link. A deletion names the link as it was last
// reported. A link reported under another name before, such as the node's own
// interface until its stitch interface got marked, is first reported deleted
// under that name, so that clients do not keep both; it is then new to them.
func (w *netlinkWatcher) emit(registry *netlinkRegistry, action string, snapshot ifaceSnapshot) {
	if w.container == nil {
		return
	}

	if action == "delete" {
		attributes := interfaceAttributes(w.container, snapshot)
		if previous, ok := w.reported[snapshot.Index]; ok {
			attributes = previous.attributes
		}

		delete(w.reported, snapshot.Index)
		registry.sendInterfaceEvent(w.container, action, attributes, time.Now())

		return
	}

	attributes := interfaceAttributes(w.container, snapshot)
	if w.track(registry, snapshot.Index, attributes) && action == "update" {
		action = "create"
	}

	registry.sendInterfaceEvent(w.container, action, attributes, time.Now())
}

// emitStats reports the counters of a link, under the name emit reports it.
func (w *netlinkWatcher) emitStats(
	registry *netlinkRegistry,
	snapshot ifaceSnapshot,
	metrics ifaceStatsMetrics,
) {
	if !registry.includeStats || w.container == nil || !snapshot.HasStats {
		return
	}

	attributes := interfaceAttributes(w.container, snapshot)
	if w.track(registry, snapshot.Index, attributes) {
		registry.sendInterfaceEvent(
			w.container,
			"create",
			maps.Clone(attributes),
			metrics.Timestamp,
		)
	}

	interfaceStatsAttributes(attributes, metrics)
	registry.sendInterfaceEvent(w.container, "stats", attributes, metrics.Timestamp)
}

// track records what the link at index is reported as. When it was reported
// under another name before, it reports that name deleted and returns true.
func (w *netlinkWatcher) track(
	registry *netlinkRegistry,
	index int,
	attributes map[string]string,
) bool {
	if w.reported == nil {
		w.reported = make(map[int]reportedInterface)
	}

	previous, known := w.reported[index]

	since := time.Now()
	if known {
		since = previous.since
	}

	w.reported[index] = reportedInterface{attributes: maps.Clone(attributes), since: since}

	if !known || previous.attributes["ifname"] == attributes["ifname"] {
		return false
	}

	registry.sendInterfaceEvent(w.container, "delete", previous.attributes, time.Now())

	return true
}

func firstContainerName(container *clabruntime.GenericContainer) string {
	if container == nil || len(container.Names) == 0 {
		return ""
	}

	return container.Names[0]
}

func containerLabel(container *clabruntime.GenericContainer) string {
	if container == nil || container.Labels == nil {
		return ""
	}

	return container.Labels[clabconstants.Containerlab]
}

// interfaceSnapshotAttributes are the attributes every interface event reports for the
// interface itself.
func interfaceSnapshotAttributes(snapshot ifaceSnapshot) map[string]string {
	attributes := map[string]string{
		"ifname": snapshot.Name,
		"index":  strconv.Itoa(snapshot.Index),
		"mtu":    strconv.Itoa(snapshot.MTU),
		"state":  snapshot.OperState,
		"type":   snapshot.Type,
	}

	if snapshot.Alias != "" {
		attributes["alias"] = snapshot.Alias
	}

	if snapshot.MAC != "" {
		attributes["mac"] = snapshot.MAC
	}

	return attributes
}

// interfaceStatsAttributes adds the counters and rates of a stats event.
func interfaceStatsAttributes(attributes map[string]string, metrics ifaceStatsMetrics) {
	attributes["rx_bytes"] = strconv.FormatUint(metrics.RxBytes, 10)
	attributes["tx_bytes"] = strconv.FormatUint(metrics.TxBytes, 10)
	attributes["rx_packets"] = strconv.FormatUint(metrics.RxPackets, 10)
	attributes["tx_packets"] = strconv.FormatUint(metrics.TxPackets, 10)
	attributes["rx_bps"] = strconv.FormatFloat(metrics.RxBps, 'f', -1, 64)
	attributes["tx_bps"] = strconv.FormatFloat(metrics.TxBps, 'f', -1, 64)
	attributes["rx_pps"] = strconv.FormatFloat(metrics.RxPps, 'f', -1, 64)
	attributes["tx_pps"] = strconv.FormatFloat(metrics.TxPps, 'f', -1, 64)
	attributes["interval_seconds"] = strconv.FormatFloat(metrics.Interval.Seconds(), 'f', -1, 64)
}

// labRuntimeInterfaceAttributes are the attributes of a lab runtime's interface event: those
// of the netlink interface events, for the node the runtime runs. Values the runtime could not
// read (no index or MTU without a shell in the node) are left out rather than reported as 0.
func labRuntimeInterfaceAttributes(
	lab, name string,
	iface *clablabruntime.InterfaceEventData,
) map[string]string {
	attributes := interfaceSnapshotAttributes(ifaceSnapshot{
		Index:     iface.Index,
		Name:      iface.Name,
		Alias:     iface.Alias,
		MTU:       iface.MTU,
		MAC:       iface.MAC,
		OperState: iface.OperState,
		Type:      iface.Type,
	})
	if iface.Index <= 0 {
		delete(attributes, "index")
	}
	if iface.MTU <= 0 {
		delete(attributes, "mtu")
	}

	if lab != "" {
		attributes["lab"] = lab
	}
	if name != "" {
		attributes["name"] = name
	}

	if stats := iface.Stats; stats != nil {
		interfaceStatsAttributes(attributes, ifaceStatsMetrics{
			RxBytes:   stats.RxBytes,
			TxBytes:   stats.TxBytes,
			RxPackets: stats.RxPackets,
			TxPackets: stats.TxPackets,
			RxBps:     stats.RxBps,
			TxBps:     stats.TxBps,
			RxPps:     stats.RxPps,
			TxPps:     stats.TxPps,
			Interval:  stats.Interval,
		})
	}

	return attributes
}

func interfaceAttributes(
	container *clabruntime.GenericContainer,
	snapshot ifaceSnapshot,
) map[string]string {
	attributes := interfaceSnapshotAttributes(snapshot)
	attributes["origin"] = "netlink"

	if lab := containerLabel(container); lab != "" {
		attributes["lab"] = lab
	}

	if name := firstContainerName(container); name != "" {
		attributes["name"] = name
	}

	overlayToolsInterface(container, attributes)

	// Add netem attributes if present
	if snapshot.HasNetem {
		if snapshot.Delay != "" {
			attributes["netem_delay"] = snapshot.Delay
		}
		if snapshot.Jitter != "" {
			attributes["netem_jitter"] = snapshot.Jitter
		}
		if snapshot.PacketLoss != 0 {
			attributes["netem_loss"] = strconv.FormatFloat(snapshot.PacketLoss, 'f', 2, 64) + "%"
		}
		if snapshot.Rate != 0 {
			attributes["netem_rate"] = strconv.Itoa(snapshot.Rate) + "kbit"
		}
		if snapshot.Corruption != 0 {
			attributes["netem_corruption"] = strconv.FormatFloat(
				snapshot.Corruption,
				'f',
				2,
				64,
			) + "%"
		}
	}

	return attributes
}

// overlayToolsInterface rewrites attributes to the host-side stitch interface
// when one exists, matching `inspect interfaces`.
func overlayToolsInterface(
	container *clabruntime.GenericContainer,
	attributes map[string]string,
) {
	if container == nil {
		return
	}

	lab, node := clabcore.TopoIdentity(container.Labels)
	if lab == "" || node == "" {
		return
	}

	topoName := attributes["alias"]
	if topoName == "" {
		topoName = attributes["ifname"]
	}

	tools, ok := clablinks.ToolsInterface(lab, node, topoName)
	if !ok {
		return
	}

	snapshot := snapshotFromLink(tools)
	attributes["ifname"] = snapshot.Name
	attributes["alias"] = topoName
	attributes["index"] = strconv.Itoa(snapshot.Index)
	attributes["mtu"] = strconv.Itoa(snapshot.MTU)
	attributes["state"] = snapshot.OperState
	attributes["type"] = snapshot.Type

	if snapshot.MAC != "" {
		attributes["mac"] = snapshot.MAC
	}
}

func (r *netlinkRegistry) sendInterfaceEvent(
	container *clabruntime.GenericContainer,
	action string,
	attributes map[string]string,
	timestamp time.Time,
) {
	event := aggregatedEvent{
		Timestamp:   timestamp,
		Type:        "interface",
		Action:      action,
		ActorID:     container.ShortID,
		ActorName:   firstContainerName(container),
		ActorFullID: container.ID,
		Attributes:  attributes,
	}

	select {
	case r.events <- event:
	case <-r.ctx.Done():
	}
}

func waitForNamespacePath(
	ctx context.Context,
	runtime clabruntime.ContainerRuntime,
	containerID string,
) (string, error) {
	const (
		attempts   = 5
		retryDelay = 200 * time.Millisecond
	)

	var lastErr error

	for i := 0; i < attempts; i++ {
		nsPath, err := runtime.GetNSPath(ctx, containerID)
		if err == nil && nsPath != "" {
			return nsPath, nil
		}

		if err != nil {
			lastErr = err
		}

		select {
		case <-time.After(retryDelay):
		case <-ctx.Done():
			return "", ctx.Err()
		}
	}

	if lastErr != nil {
		return "", lastErr
	}

	return "", fmt.Errorf("namespace path not ready for container %s", containerID)
}

func snapshotInterfaces(netHandle *netlink.Handle) (map[int]ifaceSnapshot, error) {
	if netHandle == nil {
		return nil, fmt.Errorf("netlink handle is nil")
	}

	links, err := netHandle.LinkList()
	if err != nil {
		return nil, fmt.Errorf("unable to list links: %w", err)
	}

	states := make(map[int]ifaceSnapshot, len(links))
	for _, link := range links {
		snapshot := snapshotFromLink(link)
		states[snapshot.Index] = snapshot
	}

	return states, nil
}

// withNetem returns the snapshot with the netem settings of its interface.
func withNetem(snapshot ifaceSnapshot, netemInfos map[int]netemInfo) ifaceSnapshot {
	if info, ok := netemInfos[snapshot.Index]; ok {
		snapshot.HasNetem = true
		snapshot.Delay = info.Delay
		snapshot.Jitter = info.Jitter
		snapshot.PacketLoss = info.PacketLoss
		snapshot.Rate = info.Rate
		snapshot.Corruption = info.Corruption
	}

	return snapshot
}

func snapshotFromLink(link netlink.Link) ifaceSnapshot {
	attrs := link.Attrs()

	snapshot := ifaceSnapshot{
		Type: link.Type(),
	}

	if attrs != nil {
		snapshot.Index = attrs.Index
		snapshot.Name = attrs.Name
		snapshot.Alias = attrs.Alias
		snapshot.MTU = attrs.MTU
		if len(attrs.HardwareAddr) > 0 {
			snapshot.MAC = attrs.HardwareAddr.String()
		}
		snapshot.OperState = attrs.OperState.String()
		if stats := attrs.Statistics; stats != nil {
			snapshot.HasStats = true
			snapshot.RxBytes = stats.RxBytes
			snapshot.TxBytes = stats.TxBytes
			snapshot.RxPackets = stats.RxPackets
			snapshot.TxPackets = stats.TxPackets
		}
	}

	return snapshot
}

type ifaceSnapshot struct {
	Index     int
	Name      string
	Alias     string
	MTU       int
	MAC       string
	OperState string
	Type      string
	HasStats  bool
	RxBytes   uint64
	TxBytes   uint64
	RxPackets uint64
	TxPackets uint64
	// Netem fields
	HasNetem   bool
	Delay      string
	Jitter     string
	PacketLoss float64
	Rate       int
	Corruption float64
}

func (s ifaceSnapshot) equal(other ifaceSnapshot) bool {
	return s.Index == other.Index &&
		s.Name == other.Name &&
		s.Alias == other.Alias &&
		s.MTU == other.MTU &&
		s.MAC == other.MAC &&
		s.OperState == other.OperState &&
		s.Type == other.Type &&
		s.HasNetem == other.HasNetem &&
		s.Delay == other.Delay &&
		s.Jitter == other.Jitter &&
		s.PacketLoss == other.PacketLoss &&
		s.Rate == other.Rate &&
		s.Corruption == other.Corruption
}

type ifaceStatsSample struct {
	RxBytes   uint64
	TxBytes   uint64
	RxPackets uint64
	TxPackets uint64
	Timestamp time.Time
}

type ifaceStatsMetrics struct {
	RxBytes   uint64
	TxBytes   uint64
	RxPackets uint64
	TxPackets uint64
	RxBps     float64
	TxBps     float64
	RxPps     float64
	TxPps     float64
	Interval  time.Duration
	Timestamp time.Time
}

func newStatsSample(snapshot ifaceSnapshot, timestamp time.Time) (ifaceStatsSample, bool) {
	if !snapshot.HasStats {
		return ifaceStatsSample{}, false
	}

	return ifaceStatsSample{
		RxBytes:   snapshot.RxBytes,
		TxBytes:   snapshot.TxBytes,
		RxPackets: snapshot.RxPackets,
		TxPackets: snapshot.TxPackets,
		Timestamp: timestamp,
	}, true
}

func (w *netlinkWatcher) collectAndEmitStats(
	netHandle *netlink.Handle,
	states map[int]ifaceSnapshot,
	statsSamples map[int]ifaceStatsSample,
	registry *netlinkRegistry,
) {
	if netHandle == nil || statsSamples == nil {
		return
	}

	now := time.Now()
	// Fetch all interfaces with one netlink call per tick instead of one call
	// per interface to reduce syscall overhead in large labs.
	currentStates, err := snapshotInterfaces(netHandle)
	if err != nil {
		log.Debugf(
			"failed to collect interface stats snapshot for container %s: %v",
			firstContainerName(w.container),
			err,
		)

		return
	}

	for idx, state := range states {
		current, ok := currentStates[idx]
		if !ok {
			continue
		}

		state.Name = current.Name
		state.Alias = current.Alias
		state.MTU = current.MTU
		state.MAC = current.MAC
		state.OperState = current.OperState
		state.Type = current.Type
		state.HasStats = current.HasStats
		state.RxBytes = current.RxBytes
		state.TxBytes = current.TxBytes
		state.RxPackets = current.RxPackets
		state.TxPackets = current.TxPackets
		states[idx] = state

		if !state.HasStats {
			delete(statsSamples, idx)

			continue
		}

		prev, ok := statsSamples[idx]
		if !ok || now.Sub(prev.Timestamp) <= 0 {
			statsSamples[idx] = ifaceStatsSample{
				RxBytes:   state.RxBytes,
				TxBytes:   state.TxBytes,
				RxPackets: state.RxPackets,
				TxPackets: state.TxPackets,
				Timestamp: now,
			}

			continue
		}

		interval := now.Sub(prev.Timestamp)
		if interval <= 0 {
			statsSamples[idx] = ifaceStatsSample{
				RxBytes:   state.RxBytes,
				TxBytes:   state.TxBytes,
				RxPackets: state.RxPackets,
				TxPackets: state.TxPackets,
				Timestamp: now,
			}

			continue
		}

		rxBytesDelta := deltaCounter(prev.RxBytes, state.RxBytes)
		txBytesDelta := deltaCounter(prev.TxBytes, state.TxBytes)
		rxPacketsDelta := deltaCounter(prev.RxPackets, state.RxPackets)
		txPacketsDelta := deltaCounter(prev.TxPackets, state.TxPackets)

		seconds := interval.Seconds()
		if seconds <= 0 {
			statsSamples[idx] = ifaceStatsSample{
				RxBytes:   state.RxBytes,
				TxBytes:   state.TxBytes,
				RxPackets: state.RxPackets,
				TxPackets: state.TxPackets,
				Timestamp: now,
			}

			continue
		}

		metrics := ifaceStatsMetrics{
			RxBytes:   state.RxBytes,
			TxBytes:   state.TxBytes,
			RxPackets: state.RxPackets,
			TxPackets: state.TxPackets,
			RxBps:     float64(rxBytesDelta) * 8 / seconds,
			TxBps:     float64(txBytesDelta) * 8 / seconds,
			RxPps:     float64(rxPacketsDelta) / seconds,
			TxPps:     float64(txPacketsDelta) / seconds,
			Interval:  interval,
			Timestamp: now,
		}

		w.emitStats(registry, state, metrics)

		statsSamples[idx] = ifaceStatsSample{
			RxBytes:   state.RxBytes,
			TxBytes:   state.TxBytes,
			RxPackets: state.RxPackets,
			TxPackets: state.TxPackets,
			Timestamp: now,
		}
	}
}

func deltaCounter(previous, current uint64) uint64 {
	if current >= previous {
		return current - previous
	}

	return current
}

const (
	msPerSec = 1000
)

type netemQuerier struct {
	nsHandle netns.NsHandle
	tcHandle *gotc.Tc
}

func newNetemQuerier(nsHandle netns.NsHandle) *netemQuerier {
	return &netemQuerier{
		nsHandle: nsHandle,
	}
}

func (q *netemQuerier) Close() {
	if q == nil || q.tcHandle == nil {
		return
	}

	q.tcHandle.Close()
	q.tcHandle = nil
}

// Query queries the TC qdiscs in the namespace and returns a map of
// interface index to netem data.
func (q *netemQuerier) Query() map[int]netemInfo {
	result := make(map[int]netemInfo)

	qdiscs, err := q.qdiscs()
	if err != nil {
		log.Debugf("failed to query tc qdiscs: %v", err)
		return result
	}

	for idx := range qdiscs {
		qdisc := &qdiscs[idx]
		if qdisc.Attribute.Kind != "netem" || qdisc.Netem == nil {
			continue
		}

		info := netemInfoFromQdisc(qdisc)
		if info.hasValues() {
			result[int(qdisc.Ifindex)] = info
		}
	}

	return result
}

func (q *netemQuerier) qdiscs() ([]gotc.Object, error) {
	if q == nil {
		return nil, fmt.Errorf("netem querier is nil")
	}

	if err := q.ensureHandle(); err != nil {
		return nil, err
	}

	qdiscs, err := clabnetem.Impairments(q.tcHandle)
	if err == nil {
		return qdiscs, nil
	}

	// Retry once by reopening the tc socket in case it became stale.
	q.Close()
	if errOpen := q.ensureHandle(); errOpen != nil {
		return nil, fmt.Errorf(
			"failed to query tc qdiscs (%v), and failed to reopen tc socket (%v)",
			err,
			errOpen,
		)
	}

	return clabnetem.Impairments(q.tcHandle)
}

func (q *netemQuerier) ensureHandle() error {
	if q == nil {
		return fmt.Errorf("netem querier is nil")
	}

	if q.tcHandle != nil {
		return nil
	}

	tcnl, err := clabnetem.NewTC(int(q.nsHandle))
	if err != nil {
		return fmt.Errorf("failed to open tc socket for netem query: %w", err)
	}

	q.tcHandle = tcnl

	return nil
}

type netemInfo struct {
	Delay      string
	Jitter     string
	PacketLoss float64
	Rate       int
	Corruption float64
}

func (n netemInfo) hasValues() bool {
	return n.Delay != "" || n.Jitter != "" || n.PacketLoss != 0 || n.Rate != 0 || n.Corruption != 0
}

func netemInfoFromQdisc(qdisc *gotc.Object) netemInfo {
	var info netemInfo

	if qdisc.Netem == nil {
		return info
	}

	if qdisc.Netem.Latency64 != nil && *qdisc.Netem.Latency64 != 0 {
		info.Delay = (time.Duration(*qdisc.Netem.Latency64) * time.Nanosecond).String()
	}

	if qdisc.Netem.Jitter64 != nil && *qdisc.Netem.Jitter64 != 0 {
		info.Jitter = (time.Duration(*qdisc.Netem.Jitter64) * time.Nanosecond).String()
	}

	if qdisc.Netem.Rate != nil && qdisc.Netem.Rate.Rate != 0 {
		info.Rate = int(qdisc.Netem.Rate.Rate * 8 / msPerSec)
	}

	if qdisc.Netem.Corrupt != nil && qdisc.Netem.Corrupt.Probability != 0 {
		info.Corruption = math.Round((float64(qdisc.Netem.Corrupt.Probability)/
			float64(math.MaxUint32)*100)*100) / 100
	}

	if qdisc.Netem.Qopt.Loss != 0 {
		info.PacketLoss = math.Round(
			(float64(qdisc.Netem.Qopt.Loss)/float64(math.MaxUint32)*100)*100) / 100
	}

	return info
}

