// interfaceSnapshotAttributes are the attributes every interface event reports for the
// interface itself.
func interfaceSnapshotAttributes(snapshot ifaceSnapshot) map[string]string {
	attributes := map[string]string{
		"ifname": snapshot.Name,
		"index":  strconv.Itoa(snapshot.Index),
		"mtu":    strconv.Itoa(snapshot.MTU),
		"state":  snapshot.OperState,
		"type":   snapshot.Type,
	}

	if snapshot.Alias != "" {
		attributes["alias"] = snapshot.Alias
	}

	if snapshot.MAC != "" {
		attributes["mac"] = snapshot.MAC
	}

	return attributes
}

// interfaceStatsAttributes adds the counters and rates of a stats event.
func interfaceStatsAttributes(attributes map[string]string, metrics ifaceStatsMetrics) {
	attributes["rx_bytes"] = strconv.FormatUint(metrics.RxBytes, 10)
	attributes["tx_bytes"] = strconv.FormatUint(metrics.TxBytes, 10)
	attributes["rx_packets"] = strconv.FormatUint(metrics.RxPackets, 10)
	attributes["tx_packets"] = strconv.FormatUint(metrics.TxPackets, 10)
	attributes["rx_bps"] = strconv.FormatFloat(metrics.RxBps, 'f', -1, 64)
	attributes["tx_bps"] = strconv.FormatFloat(metrics.TxBps, 'f', -1, 64)
	attributes["rx_pps"] = strconv.FormatFloat(metrics.RxPps, 'f', -1, 64)
	attributes["tx_pps"] = strconv.FormatFloat(metrics.TxPps, 'f', -1, 64)
	attributes["interval_seconds"] = strconv.FormatFloat(metrics.Interval.Seconds(), 'f', -1, 64)
}

// labRuntimeInterfaceAttributes are the attributes of a lab runtime's interface event: those
// of the netlink interface events, for the node the runtime runs. Values the runtime could not
// read (no index or MTU without a shell in the node) are left out rather than reported as 0.
func labRuntimeInterfaceAttributes(
	lab, name string,
	iface *clablabruntime.InterfaceEventData,
) map[string]string {
	attributes := interfaceSnapshotAttributes(ifaceSnapshot{
		Index:     iface.Index,
		Name:      iface.Name,
		Alias:     iface.Alias,
		MTU:       iface.MTU,
		MAC:       iface.MAC,
		OperState: iface.OperState,
		Type:      iface.Type,
	})
	if iface.Index <= 0 {
		delete(attributes, "index")
	}
	if iface.MTU <= 0 {
		delete(attributes, "mtu")
	}

	if lab != "" {
		attributes["lab"] = lab
	}
	if name != "" {
		attributes["name"] = name
	}

	if stats := iface.Stats; stats != nil {
		interfaceStatsAttributes(attributes, ifaceStatsMetrics{
			RxBytes:   stats.RxBytes,
			TxBytes:   stats.TxBytes,
			RxPackets: stats.RxPackets,
			TxPackets: stats.TxPackets,
			RxBps:     stats.RxBps,
			TxBps:     stats.TxBps,
			RxPps:     stats.RxPps,
			TxPps:     stats.TxPps,
			Interval:  stats.Interval,
		})
	}

	return attributes
}

func interfaceAttributes(
	container *clabruntime.GenericContainer,
	snapshot ifaceSnapshot,
) map[string]string {
	attributes := interfaceSnapshotAttributes(snapshot)
	attributes["origin"] = "netlink"

	if lab := containerLabel(container); lab != "" {
		attributes["lab"] = lab
	}

	if name := firstContainerName(container); name != "" {
		attributes["name"] = name
	}

	overlayToolsInterface(container, attributes)

	// Add netem attributes if present
	if snapshot.HasNetem {
		if snapshot.Delay != "" {
			attributes["netem_delay"] = snapshot.Delay
		}
		if snapshot.Jitter != "" {
			attributes["netem_jitter"] = snapshot.Jitter
		}
		if snapshot.PacketLoss != 0 {
			attributes["netem_loss"] = strconv.FormatFloat(snapshot.PacketLoss, 'f', 2, 64) + "%"
		}
		if snapshot.Rate != 0 {
			attributes["netem_rate"] = strconv.Itoa(snapshot.Rate) + "kbit"
		}
		if snapshot.Corruption != 0 {
			attributes["netem_corruption"] = strconv.FormatFloat(
				snapshot.Corruption,
				'f',
				2,
				64,
			) + "%"
		}
	}

	return attributes
}

// overlayToolsInterface rewrites attributes to the host-side stitch interface
// when one exists, matching `inspect interfaces`.
func overlayToolsInterface(
	container *clabruntime.GenericContainer,
	attributes map[string]string,
) {
	if container == nil {
		return
	}

	lab, node := clabcore.TopoIdentity(container.Labels)
	if lab == "" || node == "" {
		return
	}

	topoName := attributes["alias"]
	if topoName == "" {
		topoName = attributes["ifname"]
	}

	tools, ok := clablinks.ToolsInterface(lab, node, topoName)
	if !ok {
		return
	}

	snapshot := snapshotFromLink(tools)
	attributes["ifname"] = snapshot.Name
	attributes["alias"] = topoName
	attributes["index"] = strconv.Itoa(snapshot.Index)
	attributes["mtu"] = strconv.Itoa(snapshot.MTU)
	attributes["state"] = snapshot.OperState
	attributes["type"] = snapshot.Type

	if snapshot.MAC != "" {
		attributes["mac"] = snapshot.MAC
	}
}

func (r *netlinkRegistry) emitInterfaceEvent(
	container *clabruntime.GenericContainer,
	action string,
	snapshot ifaceSnapshot,
) {
	if container == nil {
		return
	}

	attributes := interfaceAttributes(container, snapshot)

	event := aggregatedEvent{
		Timestamp:   time.Now(),
		Type:        "interface",
		Action:      action,
		ActorID:     container.ShortID,
		ActorName:   firstContainerName(container),
		ActorFullID: container.ID,
		Attributes:  attributes,
	}

	select {
	case r.events <- event:
	case <-r.ctx.Done():
	}
}

func waitForNamespacePath(
	ctx context.Context,
	runtime clabruntime.ContainerRuntime,
	containerID string,
) (string, error) {
	const (
		attempts   = 5
		retryDelay = 200 * time.Millisecond
	)

	var lastErr error

	for i := 0; i < attempts; i++ {
		nsPath, err := runtime.GetNSPath(ctx, containerID)
		if err == nil && nsPath != "" {
			return nsPath, nil
		}

		if err != nil {
			lastErr = err
		}

		select {
		case <-time.After(retryDelay):
		case <-ctx.Done():
			return "", ctx.Err()
		}
	}

	if lastErr != nil {
		return "", lastErr
	}

	return "", fmt.Errorf("namespace path not ready for container %s", containerID)
}

func (r *netlinkRegistry) emitInterfaceStatsEvent(
	container *clabruntime.GenericContainer,
	snapshot ifaceSnapshot,
	metrics ifaceStatsMetrics,
) {
	if !r.includeStats || container == nil || !snapshot.HasStats {
		return
	}

	attributes := interfaceAttributes(container, snapshot)
	interfaceStatsAttributes(attributes, metrics)

	event := aggregatedEvent{
		Timestamp:   metrics.Timestamp,
		Type:        "interface",
		Action:      "stats",
		ActorID:     container.ShortID,
		ActorName:   firstContainerName(container),
		ActorFullID: container.ID,
		Attributes:  attributes,
	}

	select {
	case r.events <- event:
	case <-r.ctx.Done():
	}
}

func snapshotInterfaces(netHandle *netlink.Handle) (map[int]ifaceSnapshot, error) {
	if netHandle == nil {
		return nil, fmt.Errorf("netlink handle is nil")
	}

	links, err := netHandle.LinkList()
	if err != nil {
		return nil, fmt.Errorf("unable to list links: %w", err)
	}

	states := make(map[int]ifaceSnapshot, len(links))
	for _, link := range links {
		snapshot := snapshotFromLink(link)
		states[snapshot.Index] = snapshot
	}

	return states, nil
}

// withNetem returns the snapshot with the netem settings of its interface.
func withNetem(snapshot ifaceSnapshot, netemInfos map[int]netemInfo) ifaceSnapshot {
	if info, ok := netemInfos[snapshot.Index]; ok {
		snapshot.HasNetem = true
		snapshot.Delay = info.Delay
		snapshot.Jitter = info.Jitter
		snapshot.PacketLoss = info.PacketLoss
		snapshot.Rate = info.Rate
		snapshot.Corruption = info.Corruption
	}

	return snapshot
}

func snapshotFromLink(link netlink.Link) ifaceSnapshot {
	attrs := link.Attrs()

	snapshot := ifaceSnapshot{
		Type: link.Type(),
	}

	if attrs != nil {
		snapshot.Index = attrs.Index
		snapshot.Name = attrs.Name
		snapshot.Alias = attrs.Alias
		snapshot.MTU = attrs.MTU
		if len(attrs.HardwareAddr) > 0 {
			snapshot.MAC = attrs.HardwareAddr.String()
		}
		snapshot.OperState = attrs.OperState.String()
		if stats := attrs.Statistics; stats != nil {
			snapshot.HasStats = true
			snapshot.RxBytes = stats.RxBytes
			snapshot.TxBytes = stats.TxBytes
			snapshot.RxPackets = stats.RxPackets
			snapshot.TxPackets = stats.TxPackets
		}
	}

	return snapshot
}

type ifaceSnapshot struct {
	Index     int
	Name      string
	Alias     string
	MTU       int
	MAC       string
	OperState string
	Type      string
	HasStats  bool
	RxBytes   uint64
	TxBytes   uint64
	RxPackets uint64
	TxPackets uint64
	// Netem fields
	HasNetem   bool
	Delay      string
	Jitter     string
	PacketLoss float64
	Rate       int
	Corruption float64
}

func (s ifaceSnapshot) equal(other ifaceSnapshot) bool {
	return s.Index == other.Index &&
		s.Name == other.Name &&
		s.Alias == other.Alias &&
		s.MTU == other.MTU &&
		s.MAC == other.MAC &&
		s.OperState == other.OperState &&
		s.Type == other.Type &&
		s.HasNetem == other.HasNetem &&
		s.Delay == other.Delay &&
		s.Jitter == other.Jitter &&
		s.PacketLoss == other.PacketLoss &&
		s.Rate == other.Rate &&
		s.Corruption == other.Corruption
}

type ifaceStatsSample struct {
	RxBytes   uint64
	TxBytes   uint64
	RxPackets uint64
	TxPackets uint64
	Timestamp time.Time
}

type ifaceStatsMetrics struct {
	RxBytes   uint64
	TxBytes   uint64
	RxPackets uint64
	TxPackets uint64
	RxBps     float64
	TxBps     float64
	RxPps     float64
	TxPps     float64
	Interval  time.Duration
	Timestamp time.Time
}

func newStatsSample(snapshot ifaceSnapshot, timestamp time.Time) (ifaceStatsSample, bool) {
	if !snapshot.HasStats {
		return ifaceStatsSample{}, false
	}

	return ifaceStatsSample{
		RxBytes:   snapshot.RxBytes,
		TxBytes:   snapshot.TxBytes,
		RxPackets: snapshot.RxPackets,
		TxPackets: snapshot.TxPackets,
		Timestamp: timestamp,
	}, true
}

func (w *netlinkWatcher) collectAndEmitStats(
	netHandle *netlink.Handle,
	states map[int]ifaceSnapshot,
	statsSamples map[int]ifaceStatsSample,
	registry *netlinkRegistry,
) {
	if netHandle == nil || statsSamples == nil {
		return
	}

	now := time.Now()
	// Fetch all interfaces with one netlink call per tick instead of one call
	// per interface to reduce syscall overhead in large labs.
	currentStates, err := snapshotInterfaces(netHandle)
	if err != nil {
		log.Debugf(
			"failed to collect interface stats snapshot for container %s: %v",
			firstContainerName(w.container),
			err,
		)

		return
	}

	for idx, state := range states {
		current, ok := currentStates[idx]
		if !ok {
			continue
		}

		state.Name = current.Name
		state.Alias = current.Alias
		state.MTU = current.MTU
		state.MAC = current.MAC
		state.OperState = current.OperState
		state.Type = current.Type
		state.HasStats = current.HasStats
		state.RxBytes = current.RxBytes
		state.TxBytes = current.TxBytes
		state.RxPackets = current.RxPackets
		state.TxPackets = current.TxPackets
		states[idx] = state

		if !state.HasStats {
			delete(statsSamples, idx)

			continue
		}

		prev, ok := statsSamples[idx]
		if !ok || now.Sub(prev.Timestamp) <= 0 {
			statsSamples[idx] = ifaceStatsSample{
				RxBytes:   state.RxBytes,
				TxBytes:   state.TxBytes,
				RxPackets: state.RxPackets,
				TxPackets: state.TxPackets,
				Timestamp: now,
			}

			continue
		}

		interval := now.Sub(prev.Timestamp)
		if interval <= 0 {
			statsSamples[idx] = ifaceStatsSample{
				RxBytes:   state.RxBytes,
				TxBytes:   state.TxBytes,
				RxPackets: state.RxPackets,
				TxPackets: state.TxPackets,
				Timestamp: now,
			}

			continue
		}

		rxBytesDelta := deltaCounter(prev.RxBytes, state.RxBytes)
		txBytesDelta := deltaCounter(prev.TxBytes, state.TxBytes)
		rxPacketsDelta := deltaCounter(prev.RxPackets, state.RxPackets)
		txPacketsDelta := deltaCounter(prev.TxPackets, state.TxPackets)

		seconds := interval.Seconds()
		if seconds <= 0 {
			statsSamples[idx] = ifaceStatsSample{
				RxBytes:   state.RxBytes,
				TxBytes:   state.TxBytes,
				RxPackets: state.RxPackets,
				TxPackets: state.TxPackets,
				Timestamp: now,
			}

			continue
		}

		metrics := ifaceStatsMetrics{
			RxBytes:   state.RxBytes,
			TxBytes:   state.TxBytes,
			RxPackets: state.RxPackets,
			TxPackets: state.TxPackets,
			RxBps:     float64(rxBytesDelta) * 8 / seconds,
			TxBps:     float64(txBytesDelta) * 8 / seconds,
			RxPps:     float64(rxPacketsDelta) / seconds,
			TxPps:     float64(txPacketsDelta) / seconds,
			Interval:  interval,
			Timestamp: now,
		}

		registry.emitInterfaceStatsEvent(w.container, state, metrics)

		statsSamples[idx] = ifaceStatsSample{
			RxBytes:   state.RxBytes,
			TxBytes:   state.TxBytes,
			RxPackets: state.RxPackets,
			TxPackets: state.TxPackets,
			Timestamp: now,
		}
	}
}

func deltaCounter(previous, current uint64) uint64 {
	if current >= previous {
		return current - previous
	}

	return current
}

const (
	msPerSec = 1000
)

type netemQuerier struct {
	nsHandle netns.NsHandle
	tcHandle *gotc.Tc
}

func newNetemQuerier(nsHandle netns.NsHandle) *netemQuerier {
	return &netemQuerier{
		nsHandle: nsHandle,
	}
}

func (q *netemQuerier) Close() {
	if q == nil || q.tcHandle == nil {
		return
	}

	q.tcHandle.Close()
	q.tcHandle = nil
}

// Query queries the TC qdiscs in the namespace and returns a map of
// interface index to netem data.
func (q *netemQuerier) Query() map[int]netemInfo {
	result := make(map[int]netemInfo)

	qdiscs, err := q.qdiscs()
	if err != nil {
		log.Debugf("failed to query tc qdiscs: %v", err)
		return result
	}

	for idx := range qdiscs {
		qdisc := &qdiscs[idx]
		if qdisc.Attribute.Kind != "netem" || qdisc.Netem == nil {
			continue
		}

		info := netemInfoFromQdisc(qdisc)
		if info.hasValues() {
			result[int(qdisc.Ifindex)] = info
		}
	}

	return result
}

func (q *netemQuerier) qdiscs() ([]gotc.Object, error) {
	if q == nil {
		return nil, fmt.Errorf("netem querier is nil")
	}

	if err := q.ensureHandle(); err != nil {
		return nil, err
	}

	qdiscs, err := clabnetem.Impairments(q.tcHandle)
	if err == nil {
		return qdiscs, nil
	}

	// Retry once by reopening the tc socket in case it became stale.
	q.Close()
	if errOpen := q.ensureHandle(); errOpen != nil {
		return nil, fmt.Errorf(
			"failed to query tc qdiscs (%v), and failed to reopen tc socket (%v)",
			err,
			errOpen,
		)
	}

	return clabnetem.Impairments(q.tcHandle)
}

func (q *netemQuerier) ensureHandle() error {
	if q == nil {
		return fmt.Errorf("netem querier is nil")
	}

	if q.tcHandle != nil {
		return nil
	}

	tcnl, err := clabnetem.NewTC(int(q.nsHandle))
	if err != nil {
		return fmt.Errorf("failed to open tc socket for netem query: %w", err)
	}

	q.tcHandle = tcnl

	return nil
}

type netemInfo struct {
	Delay      string
	Jitter     string
	PacketLoss float64
	Rate       int
	Corruption float64
}

func (n netemInfo) hasValues() bool {
	return n.Delay != "" || n.Jitter != "" || n.PacketLoss != 0 || n.Rate != 0 || n.Corruption != 0
}

func netemInfoFromQdisc(qdisc *gotc.Object) netemInfo {
	var info netemInfo

	if qdisc.Netem == nil {
		return info
	}

	if qdisc.Netem.Latency64 != nil && *qdisc.Netem.Latency64 != 0 {
		info.Delay = (time.Duration(*qdisc.Netem.Latency64) * time.Nanosecond).String()
	}

	if qdisc.Netem.Jitter64 != nil && *qdisc.Netem.Jitter64 != 0 {
		info.Jitter = (time.Duration(*qdisc.Netem.Jitter64) * time.Nanosecond).String()
	}

	if qdisc.Netem.Rate != nil && qdisc.Netem.Rate.Rate != 0 {
		info.Rate = int(qdisc.Netem.Rate.Rate * 8 / msPerSec)
	}

	if qdisc.Netem.Corrupt != nil && qdisc.Netem.Corrupt.Probability != 0 {
		info.Corruption = math.Round((float64(qdisc.Netem.Corrupt.Probability)/
			float64(math.MaxUint32)*100)*100) / 100
	}

	if qdisc.Netem.Qopt.Loss != 0 {
		info.PacketLoss = math.Round(
			(float64(qdisc.Netem.Qopt.Loss)/float64(math.MaxUint32)*100)*100) / 100
	}

	return info
}

package links

import (
	"context"
	"crypto/sha1"
	"encoding/hex"
	"errors"
	"fmt"
	"slices"
	"sort"
	"sync"

	clabconstants "github.com/srl-labs/containerlab/constants"
	clabutils "github.com/srl-labs/containerlab/utils"
	"github.com/vishvananda/netlink"
)

type LinkVEthStitchedRaw struct {
	LinkCommonParams `               yaml:",inline"`
	Endpoints        []*EndpointRaw `yaml:"endpoints"`
}

func NewVEthStitchedRawFromVEth(v *LinkVEthRaw) *LinkVEthStitchedRaw {
	return &LinkVEthStitchedRaw{
		LinkCommonParams: v.LinkCommonParams,
		Endpoints:        v.Endpoints,
	}
}

func (*LinkVEthStitchedRaw) GetType() LinkType {
	return LinkTypeVethStitch
}

func (r *LinkVEthStitchedRaw) Resolve(params *ResolveParams) (Link, error) {
	if !isInFilter(params, r.Endpoints) {
		return nil, nil
	}

	if err := validateVEthStitched(r); err != nil {
		return nil, err
	}

	mtu := r.MTU
	if mtu == 0 {
		mtu = clabconstants.DefaultLinkMTU
	}

	l := &LinkVEthStitched{
		LinkCommonParams: r.LinkCommonParams,
		labName:          params.LabName,
	}
	l.MTU = mtu
	l.Vars = normalizeVars(l.Vars)

	segA, epA, err := buildVEthStitchSegment(params, l, r.Endpoints[0], mtu)
	if err != nil {
		return nil, err
	}

	segB, epB, err := buildVEthStitchSegment(params, l, r.Endpoints[1], mtu)
	if err != nil {
		return nil, err
	}

	l.segA, l.segB = segA, segB
	l.epA, l.epB = epA, epB

	return l, nil
}

// LinkVEthStitched is the resolved veth-stitch link: two veth segments
// (nodeA<->root-ns, nodeB<->root-ns) whose root-ns ends are joined by a tc stitch.
type LinkVEthStitched struct {
	LinkCommonParams

	lifecycleMutex sync.Mutex

	// since the stitch veth lives in the root ns, we need to ensure altnames
	// are per-lab unique.
	labName string

	segA *LinkVEth
	segB *LinkVEth

	// the two root-ns endpoints that get stitched together
	epA Endpoint
	epB Endpoint
}

func (*LinkVEthStitched) GetType() LinkType {
	return LinkTypeVethStitch
}

func (l *LinkVEthStitched) GetEndpoints() []Endpoint {
	return []Endpoint{l.segA.Endpoints[0], l.segB.Endpoints[0]}
}

// GetRuntimeEndpoints returns every material endpoint managed by the stitched link.
func (l *LinkVEthStitched) GetRuntimeEndpoints() []Endpoint {
	return []Endpoint{l.segA.Endpoints[0], l.segB.Endpoints[0], l.epA, l.epB}
}

// Deploy creates the veth segment belonging to ep.
func (l *LinkVEthStitched) Deploy(ctx context.Context, ep Endpoint) error {
	l.lifecycleMutex.Lock()
	defer l.lifecycleMutex.Unlock()

	if l.DeploymentState == LinkDeploymentStateFullDeployed {
		return nil
	}

	var err error
	switch ep {
	case l.segA.Endpoints[0]:
		err = l.segA.Deploy(ctx, ep)
	case l.segB.Endpoints[0]:
		err = l.segB.Deploy(ctx, ep)
	default:
		return fmt.Errorf("endpoint %s does not belong to link [ %s, %s ]",
			ep, l.segA.Endpoints[0], l.segB.Endpoints[0])
	}
	if err != nil {
		return err
	}

	l.DeploymentState = LinkDeploymentStateHalfDeployed

	if l.segA.DeploymentState == LinkDeploymentStateFullDeployed &&
		l.segB.DeploymentState == LinkDeploymentStateFullDeployed {
		return l.stitchSegments(ctx)
	}

	return nil
}

// PostDeploy tags the two root-ns far ends and joins them with tc.
// if they weren't already stitched in Deploy.
func (l *LinkVEthStitched) PostDeploy(ctx context.Context) error {
	l.lifecycleMutex.Lock()
	defer l.lifecycleMutex.Unlock()

	if l.DeploymentState == LinkDeploymentStateFullDeployed {
		return nil
	}
	if l.segA.DeploymentState != LinkDeploymentStateFullDeployed ||
		l.segB.DeploymentState != LinkDeploymentStateFullDeployed {
		return fmt.Errorf("cannot stitch veth segments before both are fully deployed")
	}

	return l.stitchSegments(ctx)
}

func (l *LinkVEthStitched) stitchSegments(ctx context.Context) error {
	steps := []func() error{
		func() error { return markFarEnd(l.epB, l.segA.Endpoints[0], l.labName) },
		func() error { return markFarEnd(l.epA, l.segB.Endpoints[0], l.labName) },
		func() error { return stitch(l.epA, l.epB) },
		func() error { return stitch(l.epB, l.epA) },
	}
	for _, step := range steps {
		if err := retryTransientNetlink(ctx, "veth-stitch", step); err != nil {
			return err
		}
	}

	l.DeploymentState = LinkDeploymentStateFullDeployed

	return nil
}

func (l *LinkVEthStitched) Remove(ctx context.Context) error {
	l.lifecycleMutex.Lock()
	defer l.lifecycleMutex.Unlock()

	if l.DeploymentState == LinkDeploymentStateRemoved {
		return nil
	}

	err := errors.Join(l.segA.Remove(ctx), l.segB.Remove(ctx))

	l.DeploymentState = LinkDeploymentStateRemoved

	return err
}

// buildVEthStitchSegment builds one veth segment: the real node endpoint plus a
// root-namespace far end named with a hash.
func buildVEthStitchSegment(
	params *ResolveParams,
	owner *LinkVEthStitched,
	nodeEpRaw *EndpointRaw,
	mtu int,
) (*LinkVEth, Endpoint, error) {
	seg := NewLinkVEth()
	seg.MTU = mtu

	nodeEp, err := nodeEpRaw.Resolve(params, owner)
	if err != nil {
		return nil, nil, err
	}

	// the far end sits in the root namespace (host node) with a short hash name
	// that fits the 15 char name limit.
	farName := stitchFarEndName(params.LabName, nodeEpRaw.Node, nodeEpRaw.Iface)
	farGeneric := NewEndpointGeneric(GetHostLinkNode(), farName, seg)
	farGeneric.MAC = nodeEp.GetMac()
	farEp := NewEndpointHost(farGeneric)
	seg.Endpoints = []Endpoint{nodeEp, farEp}

	return seg, farEp, nil
}

func stitchFarEndName(labName, node, iface string) string {
	sum := sha1.Sum([]byte(labName + "\x00" + node + "\x00" + iface))
	return "clab-s-" + hex.EncodeToString(sum[:4]) // 7 + 8 = 15 chars
}

func markFarEnd(farEp, nodeEp Endpoint, labName string) error {
	l, err := netlink.LinkByName(farEp.GetIfaceName())
	if err != nil {
		return fmt.Errorf("failed to look up veth-stitch far end %q: %w", farEp.GetIfaceName(), err)
	}

	iface := nodeEp.GetIfaceAlias()
	if iface == "" {
		iface = nodeEp.GetIfaceName()
	}

	altName := StitchAltName(labName, nodeEp.GetNode().GetShortName(), iface)
	if err := netlink.LinkAddAltName(l, altName); err != nil && !isAltNameNotSupportedErr(err) {
		return fmt.Errorf("failed to add veth-stitch altname %q: %w", altName, err)
	}

	return nil
}

func validateVEthStitched(r *LinkVEthStitchedRaw) error {
	if len(r.Endpoints) != 2 {
		return fmt.Errorf(
			"veth-stitch links require exactly two endpoints, got %d",
			len(r.Endpoints),
		)
	}

	return nil
}

func (r *LinkVEthStitchedRaw) cleanupFilteredLink(
	ctx context.Context,
	labName string,
	nodesFilter []string,
) error {
	return cleanupFilteredVethStitch(ctx, labName, nodesFilter, r.Endpoints)
}

func cleanupFilteredVethStitch(
	ctx context.Context,
	labName string,
	nodesFilter []string,
	endpoints []*EndpointRaw,
) error {
	for _, altName := range filteredVethStitchAltNames(labName, nodesFilter, endpoints) {
		if err := RemoveOwnedInterface(ctx, GetHostLinkNode(), altName); err != nil {
			return fmt.Errorf("failed cleaning up veth-stitch interface %q: %w", altName, err)
		}
	}

	return nil
}

func filteredVethStitchAltNames(
	labName string,
	nodesFilter []string,
	endpoints []*EndpointRaw,
) []string {
	names := make(map[string]struct{})
	for _, ep := range endpoints {
		if ep == nil || ep.Node == "" || ep.Iface == "" ||
			!slices.Contains(nodesFilter, ep.Node) {
			continue
		}
		names[StitchAltName(labName, ep.Node, ep.Iface)] = struct{}{}
	}

	result := make([]string, 0, len(names))
	for name := range names {
		result = append(result, name)
	}
	sort.Strings(result)

	return result
}

// StitchAltName returns a unique name for veth-stitch links.
func StitchAltName(labName, node, iface string) string {
	return "clab-stitch-" + clabutils.SanitizeInterfaceName(labName+"-"+node+"-"+iface)
}

// ToolsInterface returns the host-netns interface veth-stitch (and similar
// kinds) publish for node:iface under StitchAltName, or (nil, false) if none.
// Single seam for reporting/impairing the host side of the stitch.
func ToolsInterface(labName, node, iface string) (netlink.Link, bool) {
	if labName == "" || node == "" || iface == "" {
		return nil, false
	}

	link, err := netlink.LinkByName(StitchAltName(labName, node, iface))
	if err != nil {
		return nil, false
	}

	return link, true
}

